// Revisor de juguete: ¿un bucket queda abierto a cualquiera? (formato de política de S3; evaluador propio y simplificado)
const buckets = {
  "fotos-publicas": { bloqueoPublico: false, politica: { Statement: [{ Effect: "Allow", Principal: "*", Action: "s3:GetObject", Resource: "arn:aws:s3:::fotos-publicas/*" }] } },
  "backups-clientes": { bloqueoPublico: false, politica: { Statement: [{ Effect: "Allow", Principal: "*", Action: "s3:*", Resource: "arn:aws:s3:::backups-clientes/*" }] } },
  "reportes-internos": { bloqueoPublico: false, politica: { Statement: [{ Effect: "Allow", Principal: { AWS: "arn:aws:iam::111122223333:role/contabilidad" }, Action: "s3:GetObject", Resource: "arn:aws:s3:::reportes-internos/*" }] } },
  "backups-con-bloqueo": { bloqueoPublico: true, politica: { Statement: [{ Effect: "Allow", Principal: "*", Action: "s3:GetObject", Resource: "arn:aws:s3:::backups-con-bloqueo/*" }] } },
};
function revisar(nombre, b) {
  const hallazgos = [];
  for (const s of b.politica.Statement) {
    const abierto = s.Effect === "Allow" && (s.Principal === "*" || s.Principal?.AWS === "*");
    if (!abierto) continue;
    const acciones = [].concat(s.Action);
    const escribe = acciones.some(a => a === "s3:*" || /Put|Delete/.test(a));
    hallazgos.push(escribe ? "cualquiera puede LEER Y ESCRIBIR" : "cualquiera puede LEER");
  }
  if (hallazgos.length && b.bloqueoPublico) return "política abierta, pero el bloqueo de acceso público la anula";
  return hallazgos.length ? hallazgos.join("; ") : "sin acceso anónimo";
}
for (const [n, b] of Object.entries(buckets)) console.log(n.padEnd(20), "->", revisar(n, b));

// Registro de auditoría de juguete: cada entrada incluye el hash de la anterior (SHA-256).
const enc = new TextEncoder();
async function sha(t) { const h = await crypto.subtle.digest("SHA-256", enc.encode(t)); return [...new Uint8Array(h)].map(x => x.toString(16).padStart(2, "0")).join(""); }
